with months as (select distinct date_trunc('month', date_day) as month_start, last_day(date_day) as month_last from {{ ref('time_spine') }}), eligible as (select m.member_id, ms.month_start from (select distinct member_id from {{ ref('members') }}) m cross join months ms where exists (select 1 from {{ ref('cards') }} c where c.member_id = m.member_id and c.card_type in ('悦享年卡','家庭季卡') and c.valid_from <= ms.month_last and (c.valid_until is null or ms.month_last < c.valid_until) and (c.ended_at is null or ms.month_last < c.ended_at))), agg as (select member_id, date_trunc('month', ordered_at) as month_start, count(*) as valid_order_cnt, sum(paid_cents - refund_cents) as net_cents_sum from {{ ref('orders') }} where status = 'paid' and paid_cents - refund_cents > 0 group by member_id, date_trunc('month', ordered_at)) select cast(e.month_start as varchar) || '|' || e.member_id as account_month_key, e.member_id, e.month_start, coalesce(a.valid_order_cnt, 0) as valid_order_cnt, coalesce(a.net_cents_sum, 0) as net_cents_sum from eligible e left join agg a on e.member_id = a.member_id and e.month_start = a.month_start